package com.hyzen.pharmd

import android.content.Context
import android.graphics.*
import org.json.JSONArray
import org.json.JSONObject
import java.io.File
import java.io.FileOutputStream

/** Immutable imported bytes plus reversible, bounded preview transforms.
 * A legacy page can preserve only the processed bytes that still exist. */
class ScanDraftStore(private val context: Context) {
    private val prefs = context.getSharedPreferences("hyzen_scan_draft", Context.MODE_PRIVATE)
    val folder = File(context.filesDir, "scan_draft").apply { mkdirs() }
    private fun valid(path: String) = File(path).let {
        it.canonicalFile.parentFile == folder.canonicalFile && it.isFile && it.length() > 0
    }
    fun pages(): List<String> {
        val raw = JSONArray(prefs.getString("pages", "[]"))
        return (0 until raw.length()).map { raw.getString(it) }.filter { valid(it) }
    }
    private fun records() = JSONObject(prefs.getString("pageGraph", "{}"))
    private fun blank() = JSONObject().put("geometry", JSONArray()).put("filter", "original")
    private fun copy(value: JSONObject) = JSONObject(value.toString())
    private fun write(file: File, block: (FileOutputStream) -> Unit) {
        FileOutputStream(file).use { block(it); it.fd.sync() }
    }
    private fun original(file: File, created: MutableList<File>): File {
        val raw = File.createTempFile("original_", ".image", folder)
        created.add(raw)
        write(raw) { out -> file.inputStream().use { it.copyTo(out) } }
        return raw
    }
    private fun record(path: String, all: JSONObject, created: MutableList<File>): JSONObject {
        if (all.has(path)) return copy(all.getJSONObject(path))
        // Lazy, reversible migration: never invent a missing pre-edit original.
        val raw = original(File(path), created)
        return JSONObject().put("original", raw.path).put("source", "legacy_processed")
            .put("state", blank()).put("history", JSONArray())
    }
    private fun commit(paths: List<String>, all: JSONObject, consumeCapture: Boolean = false) {
        val kept = JSONObject()
        paths.forEach { if (all.has(it)) kept.put(it, all.getJSONObject(it)) }
        val edit = prefs.edit().putString("pages", JSONArray(paths).toString()).putString("pageGraph", kept.toString())
        if (consumeCapture) edit.remove("cameraPath")
        check(edit.commit()) { "Could not save scan draft" }
    }
    fun newCapture(): File {
        require(pages().size < 30) { "Save these 30 pages before scanning more." }
        check(!prefs.contains("cameraPath")) { "Recover the pending page first." }
        val output = File.createTempFile("camera_", ".jpg", folder)
        check(prefs.edit().putString("cameraPath", output.path).putBoolean("recover", true).commit())
        return output
    }
    fun finishCapture(ok: Boolean): List<String> {
        val source = prefs.getString("cameraPath", null)?.let { File(it) }
        if (ok && source != null && valid(source.path)) {
            // Malformed camera output is retained for diagnosis but not retried forever.
            val bounds = BitmapFactory.Options().apply { inJustDecodeBounds = true }
            BitmapFactory.decodeFile(source.path, bounds)
            if (bounds.outWidth <= 0 || bounds.outHeight <= 0) {
                check(prefs.edit().remove("cameraPath").commit())
                throw IllegalArgumentException("Camera image unavailable")
            }
            addInternal(listOf(source.path), "camera_capture", true)
            source.delete() // Only after both page and pending-capture state commit.
        } else {
            check(prefs.edit().remove("cameraPath").commit())
            source?.takeIf { it.canonicalFile.parentFile == folder.canonicalFile }?.delete()
        }
        return pages()
    }
    fun add(paths: List<String>): List<String> = addInternal(paths, "imported_image", false)
    fun addProcessed(paths: List<String>): List<String> = addInternal(paths, "scanner_processed", false)
    private fun addInternal(paths: List<String>, sourceKind: String, consumeCapture: Boolean): List<String> {
        val current = pages().toMutableList()
        require(current.size + paths.size <= 30) { "Choose up to 30 pages per PDF." }
        val all = records(); val created = mutableListOf<File>()
        try {
            for (path in paths) {
                val file = File(path).canonicalFile
                require(file.path.startsWith(context.filesDir.canonicalPath + "/") || file.path.startsWith(context.cacheDir.canonicalPath + "/"))
                require(file.length() in 1..(40L * 1024 * 1024))
                val raw = original(file, created)
                val entry = JSONObject().put("original", raw.path).put("source", sourceKind)
                    .put("state", blank()).put("history", JSONArray())
                val preview = render(entry, created)
                current.add(preview.path); all.put(preview.path, entry)
            }
            commit(current, all, consumeCapture)
            return current
        } catch (e: Throwable) { created.forEach { it.delete() }; throw e }
    }
    fun replace(paths: List<String>): List<String> {
        val current = pages(); val all = records()
        require(paths.size <= 30 && paths.distinct().size == paths.size && paths.all { it in current })
        commit(paths, all)
        current.filter { it !in paths }.forEach { path ->
            File(path).delete()
            all.optJSONObject(path)?.optString("original")?.takeIf { valid(it) }?.let { File(it).delete() }
        }
        return paths
    }
    private fun change(paths: List<String>, transform: (JSONObject) -> Unit): List<String> {
        val current = pages(); val all = records(); val created = mutableListOf<File>()
        require(paths.isNotEmpty() && paths.distinct().size == paths.size && paths.all { it in current })
        val replacements = mutableMapOf<String, String>()
        try {
            for (path in paths) {
                val entry = record(path, all, created)
                transform(entry)
                val output = render(entry, created)
                all.put(output.path, entry); replacements[path] = output.path
            }
            val next = current.map { replacements[it] ?: it }
            commit(next, all)
            paths.forEach { File(it).delete() }
            return next
        } catch (e: Throwable) { created.forEach { it.delete() }; throw e }
    }
    private fun remember(entry: JSONObject) {
        val history = entry.getJSONArray("history")
        history.put(copy(entry.getJSONObject("state")))
        while (history.length() > 20) history.remove(0)
    }
    fun rotate(path: String): List<String> = change(listOf(path)) { entry ->
        remember(entry)
        val geometry = entry.getJSONObject("state").getJSONArray("geometry")
        require(geometry.length() < 128) { "Reset this page before more edits." }
        geometry.put(JSONObject().put("rotate", true))
    }
    fun edit(paths: List<String>, filter: String, crop: List<Double>?, quad: List<Double>? = null): List<String> {
        require(filter in setOf("original", "gray", "contrast", "bw"))
        if (crop != null) require(crop.size == 4 && crop.all { it.isFinite() && it in 0.0..1.0 } && crop[0] < crop[2] && crop[1] < crop[3])
        if (quad != null) ScanPerspective.validate(quad)
        require(crop == null || quad == null)
        return change(paths) { entry ->
            remember(entry)
            val state = entry.getJSONObject("state")
            if (crop != null) {
                val geometry = state.getJSONArray("geometry")
                require(geometry.length() < 128) { "Reset this page before more edits." }
                geometry.put(JSONObject().put("crop", JSONArray(crop)))
            }
            if (quad != null) {
                val geometry = state.getJSONArray("geometry")
                require(geometry.length() < 128)
                geometry.put(JSONObject().put("quad", JSONArray(quad)))
            }
            state.put("filter", filter)
        }
    }
    fun undo(path: String): List<String> = change(listOf(path)) { entry ->
        val history = entry.getJSONArray("history")
        if (history.length() > 0) entry.put("state", history.remove(history.length() - 1))
    }
    fun reset(path: String): List<String> = change(listOf(path)) { entry -> remember(entry); entry.put("state", blank()) }
    fun originalInfo(path: String): Map<String, String> {
        require(path in pages())
        val entry = records().optJSONObject(path)
        return mapOf("path" to (entry?.getString("original") ?: path), "source" to (entry?.getString("source") ?: "legacy_processed"))
    }
    fun editPreview(path: String): Map<String, Any> {
        require(path in pages())
        val entry = records().optJSONObject(path)
            ?: return mapOf("bytes" to File(path).readBytes(), "filter" to "original")
        val preview = copy(entry)
        val filter = preview.getJSONObject("state").getString("filter")
        preview.getJSONObject("state").put("filter", "original")
        val created = mutableListOf<File>()
        try { return mapOf("bytes" to render(preview, created).readBytes(), "filter" to filter) }
        finally { created.forEach { it.delete() } }
    }
    private fun render(entry: JSONObject, created: MutableList<File>): File {
        val raw = entry.getString("original"); require(valid(raw))
        var bitmap = StudioImages.load(raw, 1800)
        try {
            val state = entry.getJSONObject("state"); val ops = state.getJSONArray("geometry")
            for (index in 0 until ops.length()) {
                val op = ops.getJSONObject(index)
                val next = if (op.optBoolean("rotate")) {
                    Bitmap.createBitmap(bitmap, 0, 0, bitmap.width, bitmap.height, Matrix().apply { postRotate(90f) }, true)
                } else if (op.has("quad")) {
                    val q = op.getJSONArray("quad")
                    ScanPerspective.warp(bitmap, (0..7).map { q.getDouble(it) })
                } else {
                    val crop = op.getJSONArray("crop")
                    val l = (crop.getDouble(0) * bitmap.width).toInt().coerceIn(0, bitmap.width-1)
                    val t = (crop.getDouble(1) * bitmap.height).toInt().coerceIn(0, bitmap.height-1)
                    val r = (crop.getDouble(2) * bitmap.width).toInt().coerceIn(l+1, bitmap.width)
                    val b = (crop.getDouble(3) * bitmap.height).toInt().coerceIn(t+1, bitmap.height)
                    Bitmap.createBitmap(bitmap, l, t, r-l, b-t)
                }
                if (next !== bitmap) bitmap.recycle()
                bitmap = next
            }
            val filter = state.getString("filter")
            if (filter != "original") {
                val output = Bitmap.createBitmap(bitmap.width, bitmap.height, Bitmap.Config.ARGB_8888)
                try {
                    val color = ColorMatrix()
                    if (filter == "gray" || filter == "bw") color.setSaturation(0f)
                    if (filter == "contrast" || filter == "bw") {
                        val f = if (filter == "bw") 3.5f else 1.35f; val o = 128f * (1f-f)
                        color.postConcat(ColorMatrix(floatArrayOf(f,0f,0f,0f,o,0f,f,0f,0f,o,0f,0f,f,0f,o,0f,0f,0f,1f,0f)))
                    }
                    Canvas(output).drawBitmap(bitmap, 0f, 0f, Paint(Paint.ANTI_ALIAS_FLAG).apply { colorFilter = ColorMatrixColorFilter(color) })
                } catch (e: Throwable) { output.recycle(); throw e }
                bitmap.recycle(); bitmap = output
            }
            val file = File.createTempFile("page_", ".jpg", folder); created.add(file)
            write(file) { check(bitmap.compress(Bitmap.CompressFormat.JPEG, 90, it)) }
            return file
        } finally { bitmap.recycle() }
    }
    fun beginScan() { check(prefs.edit().putBoolean("recover", true).commit()) }
    fun needsRecovery() = prefs.getBoolean("recover", false)
    fun acknowledge() { check(prefs.edit().putBoolean("recover", false).commit()) }
    fun recover(): List<String> { if (prefs.contains("cameraPath")) finishCapture(true); return pages() }
    fun clear() {
        check(prefs.edit().clear().commit())
        // Dedicated private draft directory only; gallery and exported PDFs stay intact.
        folder.listFiles()?.filter { it.isFile && it.canonicalFile.parentFile == folder.canonicalFile }?.forEach { it.delete() }
    }
}

package com.hyzen.pharmd

import android.app.Activity
import android.content.ClipData
import android.content.Context
import android.content.Intent
import android.graphics.Bitmap
import android.graphics.Matrix
import android.graphics.Canvas
import android.graphics.Paint
import android.graphics.ColorMatrix
import android.graphics.ColorMatrixColorFilter
import android.provider.MediaStore
import androidx.core.content.FileProvider
import io.flutter.plugin.common.BinaryMessenger
import io.flutter.plugin.common.MethodChannel
import org.json.JSONArray
import java.io.File
import java.util.concurrent.Executors

/** Uses the installed camera app, without an app camera permission or a heavy
 * Play-services scanning Activity. Each confirmed capture appends one page. */
class HyzenCameraCapture(private val activity: MainActivity, messenger: BinaryMessenger) {
    private val store = ScanDraftStore(activity)
    private val worker = Executors.newSingleThreadExecutor()
    private val channel = MethodChannel(messenger, "com.hyzen.pharmd/camera_pages")
    private var pending: MethodChannel.Result? = null
    private var busy = false
    init {
        channel.setMethodCallHandler { call, result ->
            if (call.method == "capture") {
                if (pending != null || busy) { result.error("busy", "Finish this page first.", null); return@setMethodCallHandler }
                try {
                    val file = store.newCapture()
                    val uri = FileProvider.getUriForFile(activity, "${activity.packageName}.updates", file)
                    val intent = Intent(MediaStore.ACTION_IMAGE_CAPTURE).apply {
                        putExtra(MediaStore.EXTRA_OUTPUT, uri)
                        clipData = ClipData.newRawUri("Scan page", uri)
                        addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION or Intent.FLAG_GRANT_WRITE_URI_PERMISSION)
                    }
                    pending = result
                    activity.startActivityForResult(intent, REQUEST)
                } catch (_: Exception) {
                    store.finishCapture(false); store.acknowledge(); pending = null
                    result.error("camera", "Camera unavailable. Choose gallery images instead.", null)
                }
                return@setMethodCallHandler
            }
            if (busy) { result.error("busy", "Preparing your page…", null); return@setMethodCallHandler }
            busy = true
            worker.execute {
                try {
                    val answer: Any = when (call.method) {
                        "needsRecovery" -> store.needsRecovery() && pending == null
                        "recover" -> store.recover().also { store.acknowledge() }
                        "addImages" -> store.add(call.argument<List<String>>("paths") ?: emptyList())
                        "replace" -> store.replace(call.argument<List<String>>("paths") ?: emptyList())
                        "undo" -> store.undo(call.argument<String>("path") ?: "")
                        "reset" -> store.reset(call.argument<String>("path") ?: "")
                        "editPreview" -> store.editPreview(call.argument<String>("path") ?: "")
                        "originalInfo" -> store.originalInfo(call.argument<String>("path") ?: "")
                        "rotate" -> store.rotate(call.argument<String>("path") ?: "")
                        "edit" -> store.edit(call.argument<List<String>>("paths") ?: emptyList(), call.argument<String>("filter") ?: "original", call.argument<List<Double>>("crop"), call.argument<List<Double>>("quad"))
                        "clear" -> { store.clear(); true }
                        else -> { activity.runOnUiThread { busy = false; result.notImplemented() }; return@execute }
                    }
                    activity.runOnUiThread { busy = false; result.success(answer) }
                } catch (e: Throwable) {
                    activity.runOnUiThread { busy = false; result.error("scan_page", "Could not prepare this page. Try a smaller image.", null) }
                }
            }
        }
    }
    fun receive(code: Int, resultCode: Int): Boolean {
        if (code != REQUEST) return false
        val result = pending; pending = null; busy = true
        worker.execute {
            try {
                val pages = store.finishCapture(resultCode == Activity.RESULT_OK)
                if (result != null) store.acknowledge()
                activity.runOnUiThread { busy = false; result?.success(pages); channel.invokeMethod("draftReady", null) }
            } catch (_: Throwable) {
                activity.runOnUiThread { busy = false; result?.error("capture", "Could not add this page. Your earlier pages are safe.", null) }
            }
        }
        return true
    }
    fun close() { pending = null; worker.shutdown() }
    companion object { const val REQUEST = 8892 }
}

package com.hyzen.pharmd

import android.app.Activity
import android.content.Intent
import com.google.mlkit.vision.documentscanner.GmsDocumentScannerOptions
import com.google.mlkit.vision.documentscanner.GmsDocumentScanning
import com.google.mlkit.vision.documentscanner.GmsDocumentScanningResult
import io.flutter.plugin.common.BinaryMessenger
import io.flutter.plugin.common.MethodChannel
import java.io.File
import java.util.concurrent.Executors

/** Google's native document viewfinder supplies auto/manual capture, page-edge
 * correction, cleanup and multi-page review. Only JPEG output is requested:
 * Hyzen composes the final PDF once, after its durable page review. */
class HyzenDocumentScanner(private val activity: MainActivity, messenger: BinaryMessenger) {
    private val store = ScanDraftStore(activity)
    private var pending: MethodChannel.Result? = null
    private var active = false
    private val worker = Executors.newSingleThreadExecutor()
    private val channel = MethodChannel(messenger, "com.hyzen.pharmd/document_scanner")
    private val cameraChannel = MethodChannel(messenger, "com.hyzen.pharmd/camera_pages")
    private val requestCode = 8891
    init {
        channel.setMethodCallHandler { call, result ->
            if (call.method != "scan") { result.notImplemented(); return@setMethodCallHandler }
            if (active) { result.error("busy", "Finish the current scan first.", null); return@setMethodCallHandler }
            val available = 30 - store.pages().size
            if (available <= 0) { result.error("limit", "Save these 30 pages before scanning more.", null); return@setMethodCallHandler }
            pending = result
            active = true
            store.beginScan()
            val options = GmsDocumentScannerOptions.Builder()
                .setGalleryImportAllowed(true).setPageLimit(available)
                .setResultFormats(GmsDocumentScannerOptions.RESULT_FORMAT_JPEG)
                .setScannerMode(GmsDocumentScannerOptions.SCANNER_MODE_FULL).build()
            GmsDocumentScanning.getClient(options).getStartScanIntent(activity)
                .addOnSuccessListener { sender ->
                    if (active && !activity.isFinishing) {
                        try { activity.startIntentSenderForResult(sender, requestCode, null, 0, 0, 0) }
                        catch (_: Exception) { fail() }
                    }
                }.addOnFailureListener { fail() }
        }
    }
    private fun fail() {
        store.acknowledge()
        pending?.error("scanner_unavailable", "Document scanner is unavailable. Update Google Play services, or choose the basic camera / gallery.", null)
        pending = null; active = false
    }
    fun receive(code: Int, resultCode: Int, intent: Intent?): Boolean {
        if (code != requestCode) return false
        // Process results even when Android recreated this Activity and there
        // is no live MethodChannel callback to the previous Flutter isolate.
        val result = pending; pending = null
        if (resultCode != Activity.RESULT_OK) {
            active = false; store.acknowledge(); result?.success(store.pages()); return true
        }
        worker.execute {
            val staged = mutableListOf<File>()
            try {
                val pages = GmsDocumentScanningResult.fromActivityResultIntent(intent)?.pages
                    ?: error("No scanned pages returned")
                require(pages.isNotEmpty() && pages.size + store.pages().size <= 30)
                for (page in pages) {
                    val file = File.createTempFile("scan_result_", ".jpg", activity.cacheDir)
                    staged.add(file)
                    activity.contentResolver.openInputStream(page.imageUri)?.use { input ->
                        file.outputStream().use { output ->
                            val buffer = ByteArray(65536); var total = 0L
                            while (true) {
                                val n = input.read(buffer); if (n < 0) break
                                total += n; require(total <= 40L * 1024 * 1024)
                                output.write(buffer, 0, n)
                            }
                        }
                    } ?: error("Scan unavailable")
                }
                val saved = store.addProcessed(staged.map { it.path })
                // Keep recovery flag until the new Flutter screen reads it.
                activity.runOnUiThread {
                    active = false
                    result?.success(saved)
                    cameraChannel.invokeMethod("draftReady", null)
                }
            } catch (_: Throwable) {
                activity.runOnUiThread {
                    active = false
                    result?.error("scan", "Could not add scanned pages. Your earlier pages are safe.", null)
                    cameraChannel.invokeMethod("draftReady", null)
                }
            } finally { staged.forEach { it.delete() } }
        }
        return true
    }
    fun close() { pending = null; worker.shutdown() }
}

