  );
}

import 'dart:ui' as ui;
import 'dart:typed_data';
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import '../../viewer/document_bytes.dart';

class ScanPageEdit {
  const ScanPageEdit(this.filter, this.crop, this.all);
  final String filter;
  final List<double>? crop;
  final bool all;
}

class ScanPageEditor extends StatefulWidget {
  const ScanPageEditor({super.key, required this.path, this.nativeDraft = false});
  final String path;
  final bool nativeDraft;
  @override
  State<ScanPageEditor> createState() => _ScanPageEditorState();
}

class _ScanPageEditorState extends State<ScanPageEditor> {
  late final _image = _load();
  String _filter = 'original';
  bool _crop = false, _all = false;
  List<Offset> _corners = const [Offset(.03,.03), Offset(.97,.03), Offset(.97,.97), Offset(.03,.97)];
  Future<({Uint8List bytes, double ratio})> _load() async {
    Uint8List bytes;
    if (widget.nativeDraft) {
      final preview = await const MethodChannel('com.hyzen.pharmd/camera_pages')
          .invokeMapMethod<String, dynamic>('editPreview', {'path': widget.path});
      if (preview == null) throw StateError('Page preview unavailable');
      bytes = preview['bytes'] as Uint8List;
      if (mounted) setState(() => _filter = preview['filter'] as String);
    } else {
      bytes = await documentBytes(widget.path);
    }
    final codec = await ui.instantiateImageCodec(bytes, targetWidth: 1200);
    final frame = await codec.getNextFrame();
    final ratio = frame.image.width / frame.image.height;
    frame.image.dispose();
    codec.dispose();
    return (bytes: bytes, ratio: ratio);
  }

  List<double> get _matrix {
    if (_filter == 'gray' || _filter == 'bw') {
      final f = _filter == 'bw' ? 3.5 : 1.0,
          o = 128 * (1 - (_filter == 'bw' ? 3.5 : 1.0));
      return [
        .213 * f,
        .715 * f,
        .072 * f,
        0,
        o,
        .213 * f,
        .715 * f,
        .072 * f,
        0,
        o,
        .213 * f,
        .715 * f,
        .072 * f,
        0,
        o,
        0,
        0,
        0,
        1,
        0,
      ];
    }
    final f = _filter == 'contrast' ? 1.35 : 1.0, o = 128 * (1 - f);
    return [f, 0, 0, 0, o, 0, f, 0, 0, o, 0, 0, f, 0, o, 0, 0, 0, 1, 0];
  }

  void _drag(int i, Offset delta, Size size) {
    final next = [..._corners];
    next[i] = Offset(
      (next[i].dx + delta.dx / size.width).clamp(0.0, 1.0),
      (next[i].dy + delta.dy / size.height).clamp(0.0, 1.0),
    );
    for (var j = 0; j < 4; j++) {
      final a = next[(j+1)%4] - next[j];
      final b = next[(j+2)%4] - next[(j+1)%4];
      if (a.dx*b.dy-a.dy*b.dx <= .001) return;
    }
    var area = 0.0;
    for (var j = 0; j < 4; j++) {
      area += next[j].dx*next[(j+1)%4].dy-next[(j+1)%4].dx*next[j].dy;
    }
    if (area / 2 < .02) return;
    setState(() => _corners = next);
  }

  @override
  Widget build(BuildContext context) => Scaffold(
    appBar: AppBar(
      title: const Text('Adjust page'),
      actions: [
        TextButton(
          onPressed: () => Navigator.pop(
            context,
            ScanPageEdit(
              _filter,
              _crop ? _corners.expand((p) => [p.dx, p.dy]).toList() : null,
              _all,
            ),
          ),
          child: const Text('Apply'),
        ),
      ],
    ),
    body: Column(
      children: [
        Expanded(
          child: FutureBuilder(
            future: _image,
            builder: (_, s) {
              if (s.hasError) {
                return const Center(child: Text('Could not open this page.'));
              }
              if (!s.hasData) {
                return const Center(child: CircularProgressIndicator());
              }
              final data = s.data!;
              return Padding(
                padding: const EdgeInsets.all(24),
                child: Center(
                  child: AspectRatio(
                    aspectRatio: data.ratio,
                    child: LayoutBuilder(
                      builder: (c, box) => Stack(
                        clipBehavior: Clip.none,
                        children: [
                          Positioned.fill(
                            child: ColorFiltered(
                              colorFilter: ColorFilter.matrix(_matrix),
                              child: Image.memory(
                                data.bytes,
                                cacheWidth: 1200,
                                fit: BoxFit.fill,
                              ),
                            ),
                          ),
                          if (_crop) ...[
                            Positioned.fill(
                              child: IgnorePointer(
                                child: CustomPaint(
                                  painter: _CropMask(
                                    _corners,
                                    Theme.of(c).colorScheme.primary,
                                  ),
                                ),
                              ),
                            ),
                            for (var i = 0; i < 4; i++)
                              Positioned(
                                left: _corners[i].dx * box.maxWidth - 24,
                                top: _corners[i].dy * box.maxHeight - 24,
                                child: GestureDetector(
                                  key: ValueKey('crop-corner-$i'),
                                  behavior: HitTestBehavior.opaque,
                                  onPanUpdate: (d) =>
                                      _drag(i, d.delta, box.biggest),
                                  child: Container(
                                    width: 48,
                                    height: 48,
                                    decoration: BoxDecoration(
                                      shape: BoxShape.circle,
                                      color: Theme.of(c).colorScheme.primary,
                                      border: Border.all(
                                        color: Colors.white,
                                        width: 3,
                                      ),
                                    ),
                                  ),
                                ),
                              ),
                          ],
                        ],
                      ),
                    ),
                  ),
                ),
              );
            },
          ),
        ),
        SafeArea(
          top: false,
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              SingleChildScrollView(
                scrollDirection: Axis.horizontal,
                padding: const EdgeInsets.symmetric(horizontal: 16),
                child: Row(
                  children: [
                    for (final f in [
                      ('original', 'Original'),
                      ('contrast', 'Colour'),
                      ('gray', 'Gray'),
                      ('bw', 'B & W'),
                    ])
                      Padding(
                        padding: const EdgeInsets.only(right: 8),
                        child: ChoiceChip(
                          label: Text(f.$2),
                          selected: _filter == f.$1,
                          onSelected: (_) => setState(() => _filter = f.$1),
                        ),
                      ),
                  ],
                ),
              ),
              Padding(
                padding: const EdgeInsets.symmetric(horizontal: 16),
                child: Wrap(
                  spacing: 16,
                  crossAxisAlignment: WrapCrossAlignment.center,
                  children: [
                    FilterChip(
                      label: const Text('4-corner crop'),
                      avatar: const Icon(Icons.crop_rounded, size: 18),
                      selected: _crop,
                      onSelected: (v) => setState(() => _crop = v),
                    ),
                    Row(mainAxisSize: MainAxisSize.min, children: [
                      const Text('Filter all pages'),
                      Switch(value: _all, onChanged: (v) => setState(() => _all = v)),
                    ]),
                  ],
                ),
              ),
            ],
          ),
        ),
      ],
    ),
  );
}

class _CropMask extends CustomPainter {
  _CropMask(this.corners, this.color);
  final List<Offset> corners;
  final Color color;
  @override
  void paint(Canvas canvas, Size size) {
    final outline = Path()..moveTo(corners[0].dx*size.width, corners[0].dy*size.height);
    for (final p in corners.skip(1)) { outline.lineTo(p.dx*size.width, p.dy*size.height); }
    outline.close();
    final path = Path()
      ..fillType = PathFillType.evenOdd
      ..addRect(Offset.zero & size)
      ..addPath(outline, Offset.zero);
    canvas.drawPath(path, Paint()..color = Colors.black45);
    canvas.drawPath(
      outline,
      Paint()
        ..color = color
        ..style = PaintingStyle.stroke
        ..strokeWidth = 2,
    );
  }

  @override
  bool shouldRepaint(covariant _CropMask old) =>
      old.corners != corners || old.color != color;
}

