    await tester.tap(find.text('Apply'));
    await tester.pumpAndSettle();
    expect(result?.crop, hasLength(8));
    expect(result!.crop![0], greaterThan(.03));
    expect(result!.crop![2], .97);
    expect(result!.crop![3], .03);
    expect(tester.takeException(), isNull);
  });
}
